// The jackdaw Worker's entry (wrangler.jsonc `main`): OpenNext's generated worker, plus the
// live (Contact) Pac-Man rooms (docs/maze/LIVE.md). Next never imports this file.
// @ts-expect-error: generated by `opennextjs-cloudflare build`, no types.
import openNext from '../.open-next/worker.js';
import type { LiveEnv } from './live-room';

export { LiveRoom } from './live-room';

/** /live/<CODE>/<session>: a socket to that session's room. */
const ROOM = /^\/live\/([A-Z0-9]{3,8})\/([A-Za-z0-9_-]{1,64})$/;

interface Handler {
  fetch(req: Request, env: unknown, ctx: CfExecutionContext): Promise<Response>;
}

export default {
  async fetch(req: Request, env: LiveEnv, ctx: CfExecutionContext): Promise<Response> {
    const path = new URL(req.url).pathname;
    if (path.startsWith('/live/')) {
      const m = ROOM.exec(path);
      if (!m) return new Response('Not found', { status: 404 });
      if (req.headers.get('upgrade')?.toLowerCase() !== 'websocket')
        return new Response('Expected a WebSocket', { status: 426 });
      return env.LIVE_ROOM.get(env.LIVE_ROOM.idFromName(`${m[1]}:${m[2]}`)).fetch(req);
    }
    return (openNext as Handler).fetch(req, env, ctx);
  },
};
